23	func TestCheckRefusesAnIndexSetThatItsDescriptorDoesNotDescribe(t *testing.T) {
24		root, _, _ := artifactGitFixture(t)
25		if _, out := checkOutput(t, root); strings.Contains(out, "index set unavailable") || strings.Contains(out, "differ from generation") {
26			t.Fatalf("a repository with no generation is reported: %s", out)
27		}
28		if code, _, errOut := runIndex(t, root); code != 0 {
29			t.Fatalf("index: %d %s", code, errOut)
30		}
31		if _, out := checkOutput(t, root); strings.Contains(out, "index set unavailable") || strings.Contains(out, "differ from generation") {
32			t.Fatalf("a whole set is reported: %s", out)
33		}
34		// A hand-edited file while the generation is whole: the divergence branch, strict and tolerant.
35		if err := os.WriteFile(filepath.Join(root, ".pose", "indexes", "services.json"), []byte("[{\"edited\":true}]\n"), 0o644); err != nil {
36			t.Fatal(err)
37		}
38		strictCode, strictOut := checkOutput(t, root)
39		if !strings.Contains(strictOut, "index files differ from generation") || !strings.Contains(strictOut, "services.json") || !strings.Contains(strictOut, "pose index") {
40			t.Fatalf("strict check does not name the diverged file: %s", strictOut)
41		}
42		if strictCode == 0 {
43			t.Fatalf("strict check passed with a diverged index file: %s", strictOut)
44		}
45		_, tolerantDiverged := checkOutput(t, root, "--tolerant")
46		if !findingIsAWarning(tolerantDiverged, "index files differ from generation") {
47			t.Fatalf("the tolerant gate reports the divergence as something other than a warning: %s", tolerantDiverged)
48		}
49		if code, _, errOut := runIndex(t, root); code != 0 {
50			t.Fatalf("pose index over the diverged set: %d %s", code, errOut)
51		}
52		// What a commit of regenerated indexes without their descriptor leaves in a checkout: the
53		// generation directory is not committed and the legacy copy no longer matches.
54		if err := os.RemoveAll(filepath.Join(root, ".pose", "indexes", "generations")); err != nil {
55			t.Fatal(err)
56		}
57		if err := os.WriteFile(filepath.Join(root, ".pose", "indexes", "spec-graph.json"), []byte("{\"edited\":true}\n"), 0o644); err != nil {
58			t.Fatal(err)
59		}
60		code, out := checkOutput(t, root)
61		if !strings.Contains(out, "index set unavailable") || !strings.Contains(out, "spec-graph.json") || !strings.Contains(out, "pose index") {
62			t.Fatalf("strict check does not name the unavailable set: %s", out)
63		}
64		if code == 0 {
65			t.Fatalf("strict check passed with an unavailable index set: %s", out)
66		}
67		// The tolerant gate (a commit hook) warns and does not fail on this finding.
68		_, tolerant := checkOutput(t, root, "--tolerant")
69		if !findingIsAWarning(tolerant, "index set unavailable") {
70			t.Fatalf("the tolerant gate reports it as something other than a warning: %s", tolerant)
71		}
72		if code, _, errOut := runIndex(t, root); code != 0 {
73			t.Fatalf("pose index over the unavailable set: %d %s", code, errOut)
74		}
75		if _, out := checkOutput(t, root); strings.Contains(out, "index set unavailable") {
76			t.Fatalf("the repaired set is still reported: %s", out)
77		}
78	}
