80	// findingIsAWarning reports whether the line of the check output that carries the finding is a
81	// warning ("[!] warning ...") and not an error.
82	func findingIsAWarning(output, finding string) bool {
83		for _, line := range strings.Split(output, "\n") {
84			if strings.Contains(line, finding) {
85				return strings.HasPrefix(strings.TrimSpace(line), "[!] warning") || strings.HasPrefix(strings.TrimSpace(line), "[!]")
86			}
87		}
88		return false
89	}
