48	// or "AVISO" printed as-is — a Portuguese anchor in an English interface, and a
49	// counter that compared prose to decide what had failed. The state comes from
50	// the closed vocabulary, its word is rendered in the reader's language, and the
51	// untranslated anchor a tool needs is the severity in `--json`
52	// (spec pose-cli-output-rendering-system R3, R8).
53	func (checker *nativeChecker) issue(state cliout.State, message string) {
54		checker.renderer().Finding(cliout.Finding{State: state, Message: message})
55		if state == cliout.StateError {
56			checker.errors++
57		} else {
58			checker.warnings++
