331	// readGenerationFile returns the bytes of one file of the generation that match
332	// its digest: the immutable copy when it exists and matches, the legacy name
333	// when that matches. When neither matches it returns the bytes it found, so the
334	// caller can say what differed, and ok false.
335	func readGenerationFile(files Files, root, id, name, want string) (data []byte, ok bool, err error) {
336		var lastErr error
337		for _, path := range []string{filepath.Join(indexGenerationDir(root, id), name), filepath.Join(indexDir(root), name)} {
338			raw, readErr := files.ReadFile(path)
339			if readErr != nil {
340				if lastErr == nil || !errors.Is(readErr, os.ErrNotExist) {
341					lastErr = readErr
342				}
343				continue
344			}
345			if sha256Prefixed(raw) == want {
346				return raw, true, nil
347			}
348			data, lastErr = raw, nil
349		}
350		return data, false, lastErr
351	}
