353	// ReadIndexGeneration fixes the generation named by the descriptor and returns
354	// every file of it, each checked against the descriptor. It starts again if the
355	// descriptor is replaced while it reads, a bounded number of times.
356	func (s Store) ReadIndexGeneration() IndexGenerationView {
357		for attempt := 0; attempt < indexReadAttempts; attempt++ {
358			desc, raw, exists, err := readIndexDescriptor(s.fsys(), s.Root)
359			if err != nil {
360				return IndexGenerationView{Status: IndexGenerationUnavailable, Reason: err.Error()}
361			}
362			if !exists {
363				if indexPendingIn(s.fsys(), s.Root) {
364					return IndexGenerationView{Status: IndexGenerationUnavailable, Reason: "a first index generation was being published and did not commit: the index files may mix two runs; run `pose index`"}
365				}
366				return IndexGenerationView{Status: IndexGenerationLegacy, Reason: "no generation descriptor: the indexes were not published as a set"}
367			}
368			if IndexReadFault != nil {
369				IndexReadFault("after-descriptor")
370			}
371			files := map[string][]byte{}
372			diverged := []string{}
373			var problem string
374			for _, f := range desc.Files {
375				data, matched, readErr := readGenerationFile(s.fsys(), s.Root, desc.GenerationID, f.Name, f.SHA256)
376				if readErr != nil {
377					problem = fmt.Sprintf("%s of generation %s cannot be read: %v", f.Name, desc.GenerationID, readErr)
378					break
379				}
380				if !matched {
381					problem = fmt.Sprintf("%s does not match generation %s (descriptor %s, file %s)", f.Name, desc.GenerationID, f.SHA256, sha256Prefixed(data))
382					break
383				}
384				files[f.Name] = data
385				if legacy, legacyErr := s.fsys().ReadFile(filepath.Join(indexDir(s.Root), f.Name)); legacyErr != nil || sha256Prefixed(legacy) != f.SHA256 {
386					diverged = append(diverged, f.Name)
387				}
388			}
389			again, againRaw, _, againErr := readIndexDescriptor(s.fsys(), s.Root)
390			if againErr == nil && again.GenerationID == desc.GenerationID && string(againRaw) == string(raw) {
391				if problem != "" {
392					return IndexGenerationView{Status: IndexGenerationUnavailable, Reason: problem, Descriptor: desc}
393				}
394				return IndexGenerationView{Status: IndexGenerationCurrent, Descriptor: desc, Files: files, Diverged: diverged, DescriptorBytes: raw}
395			}
396		}
397		return IndexGenerationView{Status: IndexGenerationUnavailable, Reason: "the generation descriptor kept changing while it was read"}
398	}
